insert into standards (sort, grp, star, title, ref, description, points, imgs) values
  (1, 'แรงสูง', true, 'การปักเสา', 'Assy. No. 8201', 'ความเอียง แนวเบี่ยงเบน ความลึก คอนกรีตหุ้มโคน', array['เสาเอียงได้ไม่เกิน 5 องศา', 'แนวเบี่ยงเบนของสาย: เคเบิลอากาศ 0–2 องศา, สายเปลือย 0–5 องศา', 'ความลึกปักเสาดูตาราง (ใช้เครื่องคำนวณ "ความลึกปักเสา")', 'เทคอนกรีตโคนเสา ส่วนผสม ซีเมนต์ : ทราย : หิน = 1 : 3 : 5 และติดกายเทียมหรือเสาค้ำยันอย่างน้อย 7 วันให้คอนกรีตแข็งตัว', 'Assy. No. 8203 ยกเลิกแล้ว ให้ใช้ 8201 หรือ 8222 แทน'], '[]'),
  (2, 'แรงสูง', true, 'สายยึดโยง (Guy)', 'Assy. No. 8426 / 8428', 'มุม ระยะติดตั้ง Storm / Line / Fix point guys', array['ติดให้ใกล้จุดศูนย์กลางแรงดึงของสาย ทำมุม 45° ถ้าพื้นที่ไม่พอยอมให้ไม่น้อยกว่า 30°', 'ดึงสายยึดโยงให้ตึงพอเหมาะ', 'ห่วงก้านสมอบกอยู่เหนือผิวดิน 15–20 ซม. ก้านต้องไม่โค้งงอและเอียงแนวเดียวกับสายยึดโยง', 'Storm guys ติดทุกระยะ 500–1,000 ม. (พื้นที่โล่งที่ทำได้ ติดทุก 3 ต้น)', 'Line guys และ Fix point guys ติดทุกระยะ 2–3 กม.', 'ถ้าติดตั้งสายยึดโยงไม่ได้ ให้ออกแบบเป็นเสาคู่แทน', 'สายแรงสูงกับแรงต่ำบนเสาต้นเดียวกัน ต้องใส่ลูกถ้วยยึดโยงคั่น'], '[]'),
  (3, 'แรงสูง', true, 'ชนิดสายในระบบจำหน่าย', 'สรุปจากคู่มือ กฟภ.', 'สายเปลือย ACSR PIC SAC TAC ต่างกันอย่างไร', array['สายเปลือย: อลูมิเนียมล้วน ทนการกัดกร่อน ใช้งานทั่วไปและชายทะเล', 'ACSR: มีแกนเหล็ก รับแรงดึงสูง — ไม่มีการก่อสร้างใหม่', 'PIC: ฉนวน XLPE 1 ชั้นบาง ใช้แทนสายเปลือยลด Fault ชั่วคราว — ไม่จัดหาเพิ่ม', 'SAC: ฉนวน XLPE หนา ไม่มีชีลด์ ใช้แทน PIC หลีกเลี่ยงพื้นที่มลภาวะสูง', 'TAC: Fully insulated มีชีลด์ สัมผัสได้ ใช้ในที่ระยะพาดสายจำกัด'], '[]'),
  (4, 'แรงสูง', true, 'การผูกสาย SAC บนลูกถ้วย', 'Assy. No. 9575 / 9574 / 9553', 'ใช้ Tie wire แบบไหน ห้ามใช้แบบไหน', array['ใช้ Covered tie wire (ลวดอลูมิเนียมหุ้มฉนวน) หรือ Composite tie wire', 'ห้ามใช้ Bare tie wire — เพิ่มความเครียดสนามไฟฟ้า ทำให้ฉนวน SAC เสื่อมเร็ว', 'ผูกด้านบน/ด้านข้าง ตามลำดับรอบในแบบการประกอบ', 'สายเปลือย: พันด้วยลวดอลูมิเนียมแบน (Armour tape) แล้วผูก Tie wire — Assy. No. 9553'], '[]'),
  (5, 'แรงสูง', true, 'การเลือกคอน', 'คู่มือตรวจมาตรฐาน', 'คอน 2,000 / 2,500 / 3,000 มม. ใช้ที่ไหน', array['คอน 2,000 มม.: งานทั่วไป สายเปลือย + SAC (เฟส B เข้ากลางได้)', 'คอนปูน 2,500 มม. / คอนเหล็ก 100×50×5 มม. ยาว 2,500 มม.: 22 kV ใช้ได้ทั้งสายเปลือยและ SAC, 33 kV ใช้ได้เฉพาะ SAC', '33 kV สายเปลือย ใช้คอน 3,000 มม. หรือคอนเหล็ก 125×65×6 มม. ยาว 3,000 มม.', 'คอน ป.ปลา และ สระอา: 22/33 kV ใช้เฉพาะ SAC'], '[]'),
  (6, 'แรงสูง', true, 'Bond wire', 'Assy. No. 2301 / 2301B / 2425 / 3423', 'ทำไมต้องมี และต่ออย่างไร', array['เป็นทางให้กระแสลัดวงจรที่ลูกถ้วยลงดินได้สมบูรณ์ ช่วยให้อุปกรณ์ป้องกันทำงานเร็ว และป้องกันคอนแตกร้าว', 'ถ้า Bond wire ขาด แปลว่าลูกถ้วยต้นนั้นเคยลัดวงจร — ใช้สังเกตตอน Patrol', 'ไม่มี Bond wire ไฟจะอาร์คที่ Bolt ยึดคอนจนเสื่อม เคยมีกรณีคอนพลิกช่างตกเสา', 'ใช้ลวดเหล็กตีเกลียว 50/7 ตร.มม. + แคล้มป์สลัก 2 ตัว', 'OHGW ลีดลงหัวเสาทุกต้น ต่อกับลวดเหล็กตีเกลียว 25 ตร.มม.'], '[]'),
  (7, 'การต่อลงดิน', true, 'การต่อลงดิน (หม้อแปลง / แรงสูง)', 'Assy. No. 9701A / 9706', 'ค่าความต้านทาน ระยะห่างกราวด์ HV/LV', array['สายดินใช้ลวดเหล็กตีเกลียว 50 ตร.มม. หุ้มท่อ PVC จากใต้ดินขึ้นไป', 'ความต้านทานดินแต่ละจุดไม่เกิน 5 โอห์ม (พื้นที่ยากไม่เกิน 25 โอห์ม)', 'ความต้านทานรวมของนิวทรัลแรงต่ำไม่เกิน 2 โอห์ม ถ้าเกินให้ปักหลักดินเพิ่ม', 'กราวด์แรงต่ำต้องห่างกราวด์แรงสูง 20 เมตร (หม้อแปลงแขวนเสา/นั่งร้าน)', 'เชื่อมสายดินกับหลักดินด้วยความร้อน (Exothermic)', 'OHGW ต่อร่วมกับสายดินกับดักเสิร์จแรงสูง ช่วยลดความต้านทาน', 'ต่อลงดินแบบวงแหวนช่วยลดแรงดันช่วงก้าวที่โคนเสา'], '[]'),
  (8, 'แรงต่ำ', false, 'การปักเสา / เสาตอม่อ (แรงต่ำ)', 'Assy. No. 8205 / 8241 / 8221 / 8222', 'ขนาดเสา ระยะช่วงเสา ความลึกตามสภาพดิน', array['เสา คอร. 8 ม.: ระบบ 1 เฟส 2 สาย หรือ 3 สาย พร้อมสายดับไฟถนน', 'เสา คอร. 9 ม.: ระบบ 3 เฟส 4 สาย 1 หรือ 2 วงจร', 'เสา คอร. 9.70 ม.: แซมพาดสายสื่อสาร หรือใช้เมื่อติดสายยึดโยงต้นสุดไม่ได้', 'ระยะช่วงเสา (Span) ปกติไม่เกิน 40 ม.', 'ความลึก เสา 8 ม. / 9 ม.: ดินแข็งปานกลาง (ดินปนทราย) 1.50 / 1.50 ม. · ดินแข็ง (ลูกรัง กรวด ดินดาน) 1.10 / 1.20 ม. · หิน 0.70 / 0.80 ม.', 'ดินอ่อน (ดินเหนียว ดินเลน มีชั้นน้ำ) หรือพื้นที่ผู้ใช้ไฟสูงกว่าจุดปักเสา ใช้เสาตอม่อ Assy. No. 8221 / 8222'], '[]'),
  (9, 'แรงต่ำ', false, 'การติดตั้งแร็คและลูกรอก', 'Assy. No. 0205 / 0206 / 0207', 'แร็คบนเสา 8 ม. / 9 ม. ทางตรง ทางโค้ง', array['เสา 8 ม.: Assy. No. 0205, 0206 (1P2W+L, 1P3W+L, 2P3W+L)', 'เสา 9 ม.: Assy. No. 0207 — ทางตรง 0–5° และทางโค้ง 5–60°', 'ลูกรอกแรงต่ำ (Spool) เป็นฉนวนและรองรับสาย ประกอบกับแร็ค สายพาดผ่านร่องกลางลูกรอก ติดได้ทั้งแนวนอนและแนวตั้ง', 'ผูกด้วย Covered tie wire และใช้ลวดเหล็กตีเกลียว 50/7 ตร.มม. ตามแบบ'], '[]'),
  (10, 'แรงต่ำ', false, 'สมอบกและสายยึดโยง (แรงต่ำ)', 'Assy. No. 8403 / 8404 / 8408 / 8410 / 8411 / 8429 / 8431 / 8432', 'Terminal / Side guys ขนาดลวด เสาทดแทน', array['Terminal guys: รับแรงจากการเข้าปลายสาย ต่อแยกสาย และเสาที่หักมุมเกิน 60° — ติดแนวเดียวกับแรงดึงของสายแต่ละด้าน', 'Side guys: ใช้กับสายที่มีมุม 5–60°', 'ลูกถ้วยยึดโยงกันกระแสรั่วจากหัวเสาลงสายยึดโยง (8403)', '8408: สายยึดโยงเป็นเส้นเดียว ไม่มีการต่อ · 1 วงจรใช้ลวดเหล็กตีเกลียว 50 ตร.มม. · 3 วงจรใช้ 95 ตร.มม.', 'GY-03 นิยมใช้ดึงสาย 50 ACSR ข้ามถนนทางหลวง 4 เลนขึ้นไป', 'ติดสายยึดโยงไม่ได้: ใช้เสา 9.70 ม. หรือ 12.20 ม. (ตัดหัวเสา) แทนเสา 8 / 9 ม. (กวฟ.(วน) 224/2567) หรือปักเสาคู่', 'แผ่นสมอบกแรงต่ำ Assy. No. 8431 / 8432 · มือลิง 8429'], '[]'),
  (11, 'แรงต่ำ', false, 'การพาดสายและระยะหย่อนยาน', 'Assy. No. 0210 / 0304 / 9214 / 9420 / 9422', 'ชนิดสาย ABC ระยะหย่อนต่ำสุด', array['สายอลูมิเนียมหุ้ม PVC 750 V 70 °C ขนาด 25–185 ตร.มม.', 'Multiplex Cable (0304) · ABC (9214): เฟส 1 จุด = A, 2 จุด = B, 3 จุด = C, สีขาว = นิวทรัล', 'ช่วงสายไม่รับแรงดึง: ระยะหย่อนต่ำสุด 1 ม. ยาวไม่เกิน 20 ม. (0210)', 'ระยะหย่อนยานต่ำสุด: สาย 50 ตร.มม. 33 ซม. (9420) · สาย 95 ตร.มม. 27 ซม. (9422)'], '[]'),
  (12, 'แรงต่ำ', false, 'ระยะห่างความปลอดภัยสายแรงต่ำ', 'Assy. No. 9301', 'ความสูงเหนือถนน ทางเท้า หลังคา', array['เหนือทางสัญจรคนหรือยานพาหนะ: 2.90 ม. (ยานพาหนะสูงไม่เกิน 2.45 ม.)', 'ทางสำหรับคนเดินเท่านั้น: ลดเหลือ 2.60 ม.', 'เหนือทางรถบรรทุก / ทางหลวง: 5.50 ม. (6.00 ม.) — รถสูงไม่เกิน 4.30 ม.', 'เหนือหลังคา / ระเบียงที่คนเข้าถึงได้: 2.40 ม. · หลังคาที่คนเข้าไม่ถึง: 0.15 ม.', 'แนวระดับ: ผนังด้านปิด / ป้ายโฆษณา 0.15 ม. · สะพานลอยคนข้าม 0.15 ม.'], '[]'),
  (13, 'แรงต่ำ', false, 'การผูกสายกับลูกรอก', 'Assy. No. 9527 / 9527A', 'Tie wire ความยาว การผูกแร็คแต่ละแบบ', array['ผูกสายอลูมิเนียมหุ้มฉนวนแรงต่ำด้วย Covered tie wire หรือ Tie wire อลูมิเนียมกลมก็ได้', 'Tie wire ยาว 1.8 ม. สำหรับพาดสายบนหัวเสา · 1.2 ม. สำหรับพาดสายเมนชายคา', '9527 และ 9527A แยกตามรูปแบบแร็ค — ดูแบบประกอบ'], '[]'),
  (14, 'แรงต่ำ', false, 'การต่อ เชื่อม และแยกสาย', 'Assy. No. 9528 / 9531 / 9558', 'Connector ชนิดบีบ IPC การพันเทป', array['พันเทป PVC ทุกจุดต่อ: PG connector, connector ชนิดบีบ, connector เข้าปลายสาย, จุดต่อกับดักเสิร์จ — ห้ามปล่อยไม่พันเทป', 'Connector ชนิดบีบ H-type: สายเมนต้องเป็นอลูมิเนียมเท่านั้น สายแยกเป็นอลูมิเนียมหรือทองแดง จำนวนรอยบีบเป็นเลขคู่ บีบตามลำดับในแบบ', 'Insulation Piercing Connector (IPC) ใช้แยกสายหุ้มฉนวน (9531)', '9558: จำนวนตามประมาณการ'], '[]'),
  (15, 'แรงต่ำ', false, 'การเข้าปลายสาย (แรงต่ำ)', 'Assy. No. 0209 / 0209A / 0211 / 9528', 'ขั้นตอน แรงบิดสลัก ปรีฟอร์ม', array['0209 เสาต้นสุดท้าย · 0211 เข้าปลายสาย 2 ข้าง · พันเทป PVC 2 ม. ต่อจุด', 'ขั้นตอน: เลือก connector ให้เหมาะกับขนาดสาย → ปอกฉนวนตรงจุดที่ connector จับ → ประกอบตามแบบ → ขันสลักให้แน่น', 'แรงบิด (Torque): M8 = 2.0 kg-m · M10 = 2.5 kg-m · M12 = 5.0 kg-m', 'ใช้ปรีฟอร์มแรงต่ำแทน connector เข้าปลายสายได้ ขนาด 25 / 50 / 95 ตร.มม. (0209A, อนุมัติ ผวก. 17 พ.ค. 2561)'], '[]'),
  (16, 'แรงต่ำ', false, 'กับดักเสิร์จแรงต่ำ', 'Assy. No. 0401', 'สเปก จุดติดตั้ง ระยะห่าง', array['สเปก: ระบบ 400 V, Rated 480 V, In(max) 5 (10) kA, Up 2 kV', 'ติดที่: ต้นหม้อแปลง · ปลาย Sealing end ของเคเบิลใต้ดิน · จุดแยกสายที่ห่างกับดักเสิร์จตัวอื่น ≥ 200 ม. · ปลายสายและปลายสาขา', 'ติดทุกระยะไม่เกิน 400 ม. (และพื้นที่ฟ้าผ่าบ่อยตามแบบ)', 'ติดเฟสละ 1 ชุด (มีไฟถนนเพิ่มอีก 1 ชุด) ติดแบบเฉียงหรือสลับไปมา', 'ติดห่างอุปกรณ์ที่ต้องป้องกันมากเกินไป อุปกรณ์จะเสี่ยงต่อแรงดันเกิน'], '[]'),
  (17, 'แรงต่ำ', false, 'คอน LT, LT Switch และฟิวส์แรงต่ำ', 'Assy. No. 2719A / 3715A / 0604 / 0409A / 0409B', 'ลำดับเฟส เลือกขนาดฟิวส์ FSD', array['คอน คอร.สปัน 100×100×2,500 มม. พ่นสี / ทำเครื่องหมายเฟส a b c · หม้อแปลง 1 เฟสใช้ 100×100×1,500 มม. (2,500 มม. เมื่อเพิ่มเฟสหรือมีสายดับไฟถนน)', 'ลำดับเฟส หม้อแปลงแขวนเสาเดี่ยว ขนานไลน์: วงจร 1 ซ้าย วงจร 2 ขวา ให้เฟส C เข้าหาเสา · ตั้งฉากไลน์: วงจร 1 ด้านถนน วงจร 2 ด้านอาคาร เฟส C เข้าหาอาคาร', 'LT Switch ทนกระแส 400 A แรงดัน 500 V ต่อด้านเอาต์พุตหม้อแปลง', 'เลือกฟิวส์: มากกว่ากระแสโหลดสูงสุดของวงจร (≤ 125%) และไม่เกินกระแสใช้งานของสาย', 'ผลรวม HRC ทุก Feeder ไม่เกิน 125% ของพิกัดกระแสด้านแรงต่ำหม้อแปลง · สายแรงต่ำไม่เกิน 95 ตร.มม.', 'กระแส: 1 เฟส I = S / 230 · 3 เฟส I = S / (1.732 × 400)', 'FSD (0409A / 0409B): ใช้ในชุมชนหนาแน่น หมู่บ้านจัดสรร จุดที่มีข้อร้องเรียน ไฟดับจากสัตว์ หรือต้องการความสวยงาม'], '[]'),
  (18, 'การต่อลงดิน', false, 'การต่อลงดิน (แรงต่ำ)', 'Assy. No. 9701A / 9703A / 9704A', 'นิวทรัลลงดิน ค่าความต้านทาน ระยะ', array['ต่อนิวทรัลลงดินที่ตำแหน่งกับดักเสิร์จแรงต่ำ ยกเว้นต้นหม้อแปลง ให้ลงดินที่เสาถัดไปห่าง ≥ 20 ม.', 'ค่าความต้านทานดินรวมของนิวทรัลแรงต่ำต่อหม้อแปลง 1 เครื่อง ไม่เกิน 2 โอห์ม', 'พื้นที่ฟ้าผ่ารุนแรง ต่อลงดินทุกระยะไม่เกิน 100 ม.', 'ต้นนั่งร้านที่มีกับดักเสิร์จแรงต่ำ ให้แยกสายนิวทรัลห่างออกไป 20 ม.', 'เชื่อมสายดินด้วยความร้อน · ห้ามใช้สายหุ้มฉนวนแรงต่ำเป็นสายดิน · ต้องต่อสายดินตู้มิเตอร์', 'เลือกแบบกราวด์ใช้เครื่องคำนวณ "เลือกแบบการต่อลงดิน" (ตัวอย่างในเล่ม: 26.6 Ω → 69.81 Ω-m)'], '[]'),
  (19, 'ไฟสาธารณะ', false, 'การติดตั้งสวิตช์เวลาและมิเตอร์ไฟถนน', 'Assy. No. 0810', 'Time switch บนเสาหม้อแปลง / เสาแรงต่ำ', array['แบบ A บนเสาหม้อแปลง 1 เฟส · แบบ B บนเสาหม้อแปลง 3 เฟส (นั่งร้าน) · แบบ C บนเสาในระบบแรงต่ำ (แบบเลขที่ SAI-015/26009 รวม 6 แผ่น)', 'Time switch แบบติดภายนอก เช่น Horstmann 30 A, Tork 40 A — สายเข้า 30 A ใช้ 10–16 ตร.มม. · 40 A ใช้ 16–25 ตร.มม.', 'ใช้สายทองแดงหุ้ม PVC 750 V 75 °C แกนเดี่ยว · Time switch ยี่ห้อ Tork ให้ต่อด้วยหางปลาทองแดง', 'มิเตอร์ 1 เฟส 2 สาย 220 V 20(40) A ชนิดกันน้ำ ติดบนแผ่นไม้รอง 60×20×2 ซม.', 'กรณีตั้งหม้อแปลงเฉพาะไฟถนน ให้ติด LT fuse switch ที่ต้นหม้อแปลงเพื่อป้องกันวงจรไฟถนน', 'จำนวนโคม ขนาด Time switch และฟิวส์ ดูแบบ SAI-015/23039 (Assy. No. 0807)'], '[]'),
  (20, 'ไฟสาธารณะ', false, 'ชุดวัสดุไฟสาธารณะ (SL) ในโปรแกรมประมาณการ', 'โปรแกรมประมาณการ งาน SL', 'ตัวอย่างคีย์วัสดุ 1 ชุด / 2 ชุด', array['Photo electric control 1 เฟส 220 V 30 A', 'L.T. fuse switch 1×400 A 500 V และ HRC fuse 32–36 A', 'Lightning arrester 250–500 V 2.5–5 kA', 'Cable lug (NEMA hole, compression) 35 ตร.มม. และ Clevis สำหรับติดตั้ง', 'ดูจำนวนต่อชุดจากรูปตัวอย่าง 1 ชุด / 2 ชุด'], '[["ตัวอย่าง 1 ชุด","sl-set1.jpg"],["ตัวอย่าง 2 ชุด","sl-set2.jpg"]]');
